@Component("featureSet-handler")
@ProcessingGroup("featureSet-processing-group")
public class FeatureSetEventHandler {
	
	// core constructor
	FeatureSetEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateFeatureSetEvent
     */
    @EventHandler
    public void handle( CreateFeatureSetEvent event) {
        entityManager.persist(new FeatureSet(event.getFeatureSetId(), event.getName(), event.getRefreshSchedule(), event.getWorkspace(), event.getFeatures(), event.getDatasets(), event.getModels(), event.getModelVersions(), event.getTags(), event.getStoreType()));
    }

    /*
     * @param	event UpdateFeatureSetEvent
     */
    @EventHandler
    public FeatureSet handle( UpdateFeatureSetEvent event) {
    	entityManager.merge(new FeatureSet(event.getFeatureSetId(), event.getName(), event.getRefreshSchedule(), event.getWorkspace(), event.getFeatures(), event.getDatasets(), event.getModels(), event.getModelVersions(), event.getTags(), event.getStoreType()));
    }
    
    /*
     * @param	event DeleteFeatureSetEvent
     */
    @EventHandler
    public void on( DeleteFeatureSetEvent event) {
    	FeatureSet entity = new FeatureSet();
   
    	// ------------------------------------------
    	// apply the FeatureSetId
    	// ------------------------------------------
    	entity.setFeatureSetId( event.getFeatureSetId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final FeatureSetRepository featureSetEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(FeatureSetEventHandler.class.getName());

}
